 "content": "def transform(grid):
    # Find the constant separator. The target is always the region before it;
    # recolor the panel's minority color 3, leaving the majority background.
    sep_row = next((r for r,row in enumerate(grid) if len(set(row)) == 1), None)
    if sep_row is not None:
        panel = grid[:sep_row]
    else:
        sep_col = next(c for c in range(len(grid[0]))
