        panel = [row[:sep_col] for row in grid]
    from collections import Counter
    counts = Counter(x for row in panel for x in row)
    bg = counts.most_common(1)[0][0]
    fg = min((v for v in counts if v != bg), key=lambda v: counts[v])
    return [[3 if v == fg else bg for v in row] for row in panel]
